import{_ as o}from"./chunks/quick_control_icon.Cc9UwUrp.js";import{_ as t,o as i,c as a,a6 as c}from"./chunks/framework.mtgKxyez.js";const u=JSON.parse('{"title":"6. Self Practice","description":"","frontmatter":{},"headers":[],"relativePath":"en/basic/6.md","filePath":"en/basic/6.md"}'),n={name:"en/basic/6.md"};function d(l,e,s,r,h,m){return i(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="_6-self-practice" tabindex="-1">6. Self Practice <a class="header-anchor" href="#_6-self-practice" aria-label="Permalink to &quot;6. Self Practice&quot;">​</a></h1><h2 id="task" tabindex="-1">Task <a class="header-anchor" href="#task" aria-label="Permalink to &quot;Task&quot;">​</a></h2><p>Detect and pick up a mahjong block, then place it into the small board for mahjong blocks. A Landmark will be placed on the board. The positions of both the mahjong block and the board are not fixed. After the flow ends, the project must exit the execution screen by itself. Every task after this should also exit automatically.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ol><li>The mahjong block position is not fixed. Check whether the arm can accurately pick it up. It is recommended not to rotate the block more than 180°.</li><li>The board position is not fixed. Check whether the arm can accurately place the mahjong block into a slot. It is recommended not to rotate the board more than 180°.</li><li>After the flow ends, check whether it automatically exits the project execution screen.</li></ol><h2 id="answer" tabindex="-1">Answer <a class="header-anchor" href="#answer" aria-label="Permalink to &quot;Answer&quot;">​</a></h2><ol><li><code>Point</code> (Robot Base): set a <code>Point</code> at the initial position. It should be high enough to avoid collisions when moving to the vision task position.</li><li><code>Vision</code> (Positioning, Robot Base): move above the mahjong block area, set an <code>Object Positioning</code> vision task, and recognize the <strong>TM</strong> logo on the mahjong block. This automatically creates Vision Base.</li><li><code>Point</code> (Vision Base): move the arm down above the mahjong block to a position where it can grip the block. Do not move the mahjong block. You can use <img src="'+o+'" alt="Quick Control icon" style="width:25px;display:inline;vertical-align:middle;margin:0 5px;"> and the controller <code>+</code> and <code>-</code> for fine adjustment.</li><li><code>Set</code>: set end module <code>DO_0</code> to <code>H</code>, then press <code>Output Test</code> to grip the mahjong block.</li><li><code>Wait for</code>: wait <code>500 ms</code> to ensure the block is gripped.</li><li><code>Move</code>: set <code>Z</code> to <code>-100 mm</code> so the arm will not collide. This step can also be replaced with another vertical-up <code>Point</code>.</li><li><code>Point</code> (Robot Base): move to a higher position to prepare for the board vision task.</li><li><code>Vision</code> (Positioning, Robot Base): move above the small board, set a <code>TM Landmark</code> vision task, and recognize the Landmark on the board. This automatically creates Vision Base.</li><li><code>Point</code> (Vision Base): move the arm onto the board and align the gripped mahjong block with one board slot. Do not move the mahjong block. You can use <img src="'+o+'" alt="Quick Control icon" style="width:25px;display:inline;vertical-align:middle;margin:0 5px;"> and the controller <code>+</code> and <code>-</code> for fine adjustment.</li><li><code>Set</code>: set end module <code>DO_0</code> to <code>L</code>, then press <code>Output Test</code> to release the mahjong block.</li><li><code>Wait for</code>: wait <code>500 ms</code> to ensure the block is released.</li><li><code>Move</code>: set <code>Z</code> to <code>-100 mm</code> so the arm will not collide. This step can also be replaced with another vertical-up <code>Point</code>.</li><li><code>Point</code> (Robot Base): set a <code>Point</code> at the ending position.</li><li><code>Stop</code></li></ol><div class="tip custom-block"><p class="custom-block-title">Small Tip</p><p>For every <code>Vision</code> <code>Miss</code>, you can connect it to a <code>Goto</code> node and loop it back to that <code>Vision</code>.</p></div>',8)])])}const k=t(n,[["render",d]]);export{u as __pageData,k as default};
